package com.ballsclient.core.module.telemetry.bandwidth;

import com.ballsclient.core.module.Category;
import com.ballsclient.core.module.Module;
import com.ballsclient.core.setting.BooleanSetting;
import com.ballsclient.core.setting.NumberSetting;

/**
 * EntityBandwidthProfiler — Measures network traffic generated by entity spawn, movement, velocity,
 * and metadata update packets in render distance.
 */
public class EntityBandwidthProfiler extends Module {
    private final BooleanSetting groupByEntityType = new BooleanSetting("GroupByEntityType", "Aggregates byte consumption by entity registry type", true);
    private final BooleanSetting highlightHighBandwidthEntities = new BooleanSetting("HighlightHighBandwidthEntities", "Highlights entities consuming disproportionate bandwidth", true);
    private final NumberSetting profilerPeriodSeconds = new NumberSetting("ProfilerPeriodSeconds", "Entity bandwidth accumulation window in seconds", 10.0, 2.0, 60.0, 2.0);

    public EntityBandwidthProfiler() {
        super("entity-bandwidth-profiler", "Entity Bandwidth Profiler", "Measures network traffic generated by entity spawn, movement, velocity, and metadata update packets in render distance.", Category.NETWORK);
        addSettings(groupByEntityType, highlightHighBandwidthEntities, profilerPeriodSeconds);
    }

    public BooleanSetting getGroupByEntityType() {
        return groupByEntityType;
    }

    public BooleanSetting getHighlightHighBandwidthEntities() {
        return highlightHighBandwidthEntities;
    }

    public NumberSetting getProfilerPeriodSeconds() {
        return profilerPeriodSeconds;
    }
}
